import{_t as e,it as t,n,rt as r}from"./chunks/framework.D9LADW4G.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788812764000}`),a={name:`guide/faq.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="every-call-returns-http-401" tabindex="-1">Every call returns HTTP 401 <a class="header-anchor" href="#every-call-returns-http-401" aria-label="Permalink to “Every call returns HTTP 401”">​</a></h2><p>Two causes, in order of likelihood:</p><ol><li><strong>2FA is enabled</strong> on the account. The wg-easy API speaks Basic Authentication only and rejects TOTP-protected accounts. The error message says so explicitly. Disable TOTP for that account or use another one.</li><li>The username or password is wrong. They are the <strong>web UI login</strong>, not an API token — wg-easy has no separate API credentials.</li></ol><h2 id="the-server-starts-but-every-tool-call-fails-with-missing-required-environment-variable-s" tabindex="-1">The server starts but every tool call fails with &quot;missing required environment variable(s)&quot; <a class="header-anchor" href="#the-server-starts-but-every-tool-call-fails-with-missing-required-environment-variable-s" aria-label="Permalink to “The server starts but every tool call fails with &quot;missing required environment variable(s)&quot;”">​</a></h2><p>The server started without credentials, which it does on purpose so registries can enumerate its tools. Your MCP client is not passing the <code>env</code> block through. Check the config for the client you are using in <a href="/guide/clients">Connecting clients</a>, and remember that <code>claude mcp add</code> needs each variable as its own <code>-e</code> flag before the <code>--</code>.</p><h2 id="get-server-info-reports-an-error-for-the-information-section" tabindex="-1"><code>get_server_info</code> reports an error for the <code>information</code> section <a class="header-anchor" href="#get-server-info-reports-an-error-for-the-information-section" aria-label="Permalink to “get_server_info reports an error for the information section”">​</a></h2><p><code>/api/information</code> fetches the latest wg-easy release from GitHub, and it returns <code>HTTP 500</code> when the container has no outbound internet access. The tool collects its three sections independently, so <code>general</code> and <code>interface</code> still come back normally. If you do not need release-update status, this is cosmetic; otherwise, give the wg-easy container egress.</p><h2 id="can-i-make-it-read-only" tabindex="-1">Can I make it read-only? <a class="header-anchor" href="#can-i-make-it-read-only" aria-label="Permalink to “Can I make it read-only?”">​</a></h2><p>Yes, since 0.4.0: <code>WG_EASY_READ_ONLY=true</code> registers <code>list_clients</code>, <code>get_client</code> and <code>get_server_info</code>, and nothing else. wg-easy itself still has no read-only account, so this is enforced by the server, not by the credentials — anything that can read the process environment still holds VPN admin.</p><p>Note that <code>get_client_config</code> and <code>get_client_qrcode</code> are <strong>not</strong> in that set, although both are reads. What they read is a client&#39;s private key in the clear, and a read-only mode that leaves key disclosure standing is not the mode its name promises. They are out of <code>WG_EASY_ALLOW_TOOLS=essential</code> for the same reason; name them where a session should also hand out configurations.</p><p>Beyond the switch:</p><ul><li>use an MCP client that asks before running non-read-only tools — the tools carry <code>readOnlyHint</code>, <code>destructiveHint</code> and <code>idempotentHint</code> annotations for exactly this,</li><li>rely on the five tools that <a href="/guide/approval">ask a person</a> — <code>create_client</code>, <code>update_client</code>, <code>enable_client</code>, <code>delete_client</code> and <code>generate_one_time_link</code> — which no single call can bypass.</li></ul><h2 id="why-did-update-client-not-change-the-field-i-asked-for" tabindex="-1">Why did <code>update_client</code> not change the field I asked for? <a class="header-anchor" href="#why-did-update-client-not-change-the-field-i-asked-for" aria-label="Permalink to “Why did update_client not change the field I asked for?”">​</a></h2><p><code>update_client</code> only accepts the fields in its schema. Anything else — including wg-easy&#39;s <code>preUp</code>/<code>postUp</code>/<code>preDown</code>/<code>postDown</code> shell hooks, which run as root on the server — is dropped before the request is built, deliberately and with a test covering it. If you need a hook changed, do it in the wg-easy UI.</p><p>Note also that the wg-easy update endpoint requires the <strong>complete</strong> client object, so the tool reads the current state and merges your changes into it. A field you did not mention keeps its current value.</p><h2 id="the-tool-output-starts-with-untrusted-data" tabindex="-1">The tool output starts with &quot;[untrusted data]&quot; <a class="header-anchor" href="#the-tool-output-starts-with-untrusted-data" aria-label="Permalink to “The tool output starts with &quot;[untrusted data]&quot;”">​</a></h2><p>That is the marker described in <a href="/guide/security">Security</a>. It tells the model that client names and similar free-form fields are data, not instructions. The actual payload follows after a blank line.</p><h2 id="the-answer-carries-a-truncated-field" tabindex="-1">The answer carries a <code>truncated</code> field <a class="header-anchor" href="#the-answer-carries-a-truncated-field" aria-label="Permalink to “The answer carries a truncated field”">​</a></h2><p>An upstream payload exceeded the 60 000-character budget, so the longest strings were shortened (<code>… (N more characters omitted)</code>) or entries were dropped from the longest list. <code>truncated.fields</code> names every path that was cut with what survived and what was there, and <code>truncated.note</code> names the call that fetches the remainder — usually narrowing <code>list_clients</code> with <code>filter</code>, or switching to <code>get_client</code> for one specific client.</p><h2 id="the-output-says-the-login-is-repeated-from-memory" tabindex="-1">The output says the login is &quot;repeated from memory&quot; <a class="header-anchor" href="#the-output-says-the-login-is-repeated-from-memory" aria-label="Permalink to “The output says the login is &quot;repeated from memory&quot;”">​</a></h2><p>The instance refused the credentials, and that answer is repeated for ten seconds instead of being tried again. Every tool call carries the admin credentials, so every call is a login attempt, and a model that retries a <code>401</code> turns one wrong password into a stream of failed logins from the host you administer the VPN from. The message says when the next real attempt is possible. Fix <code>WG_EASY_USERNAME</code>/<code>WG_EASY_PASSWORD</code> and restart the server; note that the wg-easy API does not work at all while 2FA is enabled for the account.</p><h2 id="the-output-says-the-instance-answered-past-a-ceiling" tabindex="-1">The output says the instance answered past a ceiling <a class="header-anchor" href="#the-output-says-the-instance-answered-past-a-ceiling" aria-label="Permalink to “The output says the instance answered past a ceiling”">​</a></h2><p>A successful response body larger than 8 MiB is refused rather than read: the other end of the connection is not always wg-easy — a typo in <code>WG_EASY_URL</code> reaches whoever owns that name, and <code>WG_EASY_INSECURE_TLS</code> trusts whatever answers — and a body that never ends would otherwise be a server that never answers again. Narrow the request, or check that <code>WG_EASY_URL</code> points where you think it does.</p><h2 id="does-it-work-with-wg-easy-v14-or-older" tabindex="-1">Does it work with wg-easy v14 or older? <a class="header-anchor" href="#does-it-work-with-wg-easy-v14-or-older" aria-label="Permalink to “Does it work with wg-easy v14 or older?”">​</a></h2><p>No. It targets the v15 REST API. Older versions expose a different, session-based API that this server does not implement.</p><h2 id="a-wg-easy-upgrade-broke-a-tool" tabindex="-1">A wg-easy upgrade broke a tool <a class="header-anchor" href="#a-wg-easy-upgrade-broke-a-tool" aria-label="Permalink to “A wg-easy upgrade broke a tool”">​</a></h2><p>Likely. The wg-easy API is <a href="https://wg-easy.github.io/wg-easy/latest/advanced/api/" target="_blank" rel="noreferrer">not declared stable</a> and its shapes change between releases. Please <a href="https://github.com/ni-c/wg-easy-mcp/issues" target="_blank" rel="noreferrer">open an issue</a> with the wg-easy version and the failing tool — redact keys, hostnames and IPs first.</p><h2 id="where-do-i-ask-something-not-covered-here" tabindex="-1">Where do I ask something not covered here? <a class="header-anchor" href="#where-do-i-ask-something-not-covered-here" aria-label="Permalink to “Where do I ask something not covered here?”">​</a></h2><p><a href="https://github.com/ni-c/wg-easy-mcp/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> for questions and ideas; <a href="https://github.com/ni-c/wg-easy-mcp/issues" target="_blank" rel="noreferrer">Issues</a> for reproducible problems; and <a href="https://github.com/ni-c/wg-easy-mcp/security/advisories/new" target="_blank" rel="noreferrer">private reporting</a> for anything security-related.</p><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>WG_EASY_READ_ONLY</code> is set, and it is a write tool.</li><li><code>WG_EASY_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out.</li><li><code>WG_EASY_DENY_TOOLS</code> names it, possibly through a prefix such as <code>list_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot;. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p>`,35)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};